// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address target = address(123);
        uint value = 1 wei;
        c.depositsCount();
        vm.deal(address(c), 10 wei);
        vm.prank(c.owner());
        c.sendMoney(target, value);
        assertTrue(address(c).balance == 9 wei);
    }
}
